def rollback(manifest_path: Path | str, expected_sha256: str, *, fault_hook: FaultHook | None = None) -> dict[str, Any]:
    try:
        return rollback_from_manifest(manifest_path, expected_sha256, fault_hook=fault_hook)
    except CanvasFailure as exc:
        exc.operation = "rollback"
        raise

class CanvasSuccess:
    """已通过 schema 的成功 stdout 对象。"""

    value: dict[str, Any]

    def __post_init__(self) -> None:
        validate_instance("canvas-success.schema.json", self.value)

    def to_dict(self) -> dict[str, Any]:
        return dict(self.value)

class ArtifactBaseline:
    roles: dict[str, BaselineRole]

    def request_states(self) -> dict[str, dict[str, Any]]:
        return {role: dict(self.roles[role].state) for role in ROLE_ORDER}

    def manifest_states(self) -> dict[str, dict[str, Any]]:
        result: dict[str, dict[str, Any]] = {}
        for role in ROLE_ORDER:
            item = self.roles[role]
            if item.state["state"] == "absent":
                result[role] = {"state": "absent"}
            else:
                assert item.backup_path is not None
                result[role] = {
                    "state": "present",
                    "sha256": item.state["sha256"],
                    "backup_path": str(item.backup_path),
                    "backup_sha256": item.state["sha256"],
                }
        return result

